package br.com.confirmacao.patient.application;import br.com.confirmacao.patient.domain.*;import br.com.confirmacao.patient.infrastructure.PatientRepository;import br.com.confirmacao.professional.application.ProfessionalNotFoundException;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.session.domain.SessionStatus;import br.com.confirmacao.session.infrastructure.SessionAppointmentRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class PatientService{private final PatientRepository patients;private final ProfessionalRepository professionals;private final SessionAppointmentRepository sessions;public PatientService(PatientRepository p,ProfessionalRepository r,SessionAppointmentRepository s){patients=p;professionals=r;sessions=s;}@Transactional public Patient create(UUID pid,String n,LocalDate b,String phone,String e,PreferredContactChannel c,Boolean reminders){var pro=professionals.findById(pid).orElseThrow(()->new ProfessionalNotFoundException(pid));if(patients.existsByProfessionalIdAndPhone(pid,norm(phone)))throw new PatientAlreadyExistsException();var patient=new Patient(pro,n,b,phone,e,c);patient.setWhatsappRemindersEnabled(reminders,"PROFESSIONAL");return patients.save(patient);}@Transactional(readOnly=true)public Page<Patient> findAll(UUID pid,Pageable p){return patients.findAllByProfessionalId(pid,p);}@Transactional(readOnly=true)public Patient findById(UUID pid,UUID id){return patients.findByIdAndProfessionalId(id,pid).orElseThrow(()->new PatientNotFoundException(id));}@Transactional public Patient update(UUID pid,UUID id,String n,LocalDate b,String ph,String e,PreferredContactChannel c,Boolean reminders){var x=findById(pid,id);if(patients.existsByProfessionalIdAndPhoneAndIdNot(pid,norm(ph),id))throw new PatientAlreadyExistsException();x.update(n,b,ph,e,c);x.setWhatsappRemindersEnabled(reminders,"PROFESSIONAL");return x;}@Transactional public void activate(UUID p,UUID i){findById(p,i).activate();}@Transactional public void deactivate(UUID p,UUID i){var patient=findById(p,i);if(sessions.existsByProfessionalIdAndPatientIdAndStatusInAndEndsAtAfter(p,i,List.of(SessionStatus.SCHEDULED,SessionStatus.CONFIRMED),Instant.now()))throw new IllegalArgumentException("Cancele ou reagende as sessões futuras antes de desativar o paciente");patient.deactivate();}@Transactional public Patient grantConsent(UUID p,UUID i){var x=findById(p,i);x.grantConsent();return x;}@Transactional public Patient revokeConsent(UUID p,UUID i){var x=findById(p,i);x.revokeConsent();return x;}private String norm(String v){return v==null?null:v.replaceAll("\\D","");}}
